(9901, '1 Chronicles 6:43', '1 Chronicles', 6, 43, '&nbsp;يحت، جيرسون او ليوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9902, '1 Chronicles 6:44', '1 Chronicles', 6, 44, '&nbsp;د مرارى قبيلې ايتان د درېمې سندرې مشر وو. شا ته ليوى ته د هغۀ نسب‌نامه داسې ده: قيسى، عبدى، ملوک،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9903, '1 Chronicles 6:45', '1 Chronicles', 6, 45, '&nbsp;حسبياه، امصياه، خِلقياه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9904, '1 Chronicles 6:46', '1 Chronicles', 6, 46, '&nbsp;امصى، بانى، سمر،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9905, '1 Chronicles 6:47', '1 Chronicles', 6, 47, '&nbsp;محلى، موشى، مرارى او ليوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9906, '1 Chronicles 6:48', '1 Chronicles', 6, 48, '&nbsp;نورو ليويانو ته د مالِک خُدائ په کور کښې باقى ټول خِدمت حواله شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9907, '1 Chronicles 6:49', '1 Chronicles', 6, 49, '&nbsp;خو هارون او د هغۀ اولاد د خوشبويۍ نذرانې پېش کولې او هغه قربانۍ يې پېش کولې چې په قربان‌ګاه باندې سوزولے شوې. هغوئ په زيات مقدس ځائ کښې د ټول عبادت او د بنى اِسرائيلو د کفارې ادا کولو ذمه وار وُو. هغوئ دا هر څۀ د هغه اصُولو په مطابق کول کوم چې د خُدائ پاک خِدمت کوونکى موسىٰ ورته ښودلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9908, '1 Chronicles 6:50', '1 Chronicles', 6, 50, '&nbsp;دا د هارون اولاد دے: اِلى‌عزر، فينحاس، ابيسوع،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9909, '1 Chronicles 6:51', '1 Chronicles', 6, 51, '&nbsp;بُقى، عُزى، زرخياه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9910, '1 Chronicles 6:52', '1 Chronicles', 6, 52, '&nbsp;مرايوت، امرياه، اخيطوب،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9911, '1 Chronicles 6:53', '1 Chronicles', 6, 53, '&nbsp;صدوق او اخيمعض.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9912, '1 Chronicles 6:54', '1 Chronicles', 6, 54, '&nbsp;دا هغه ښارونه دى چې د هارون اولاد ته حواله شوى وُو چې هغه د قُهات قبيله ده. هغوئ ته به د هغې زمکې وړومبۍ برخه مِلاوېده کومه چې ليويانو ته حواله شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9913, '1 Chronicles 6:55', '1 Chronicles', 6, 55, '&nbsp;په دې کښې د يهوداه په علاقه کښې حبرون او د دې نه ګېرچاپېره د څرن زمکې شاملې وې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9914, '1 Chronicles 6:56', '1 Chronicles', 6, 56, '&nbsp;اګر چې د هغه ښار پټى او کلى د يفُنه زوئ کالب په حواله وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9915, '1 Chronicles 6:60', '1 Chronicles', 6, 60, '&nbsp;د بنيامين په علاقه کښې هغوئ ته دا ښارونه سره د څرن د زمکې حواله شوى وُو: جبعه، علمت او عنتوت. دا ټول ديارلس ښارونه وُو چې د هغوئ مکمل خاندان په کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9916, '1 Chronicles 6:61', '1 Chronicles', 6, 61, '&nbsp;نمرپريواتۀ طرف ته د منسى په علاقه کښې لس ښارونه د پچې په ذريعه د قُهات پاتې قبيلې ته خاندان په خاندان حواله شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9917, '1 Chronicles 6:62', '1 Chronicles', 6, 62, '&nbsp;د جيرسون قبيلې ته کورَنو په مطابق ديارلس ښارونه د يساکار، آشر، نفتالى او نمرخاتۀ طرف ته په بسن کښې د منسى په علاقو کښې حواله شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9918, '1 Chronicles 6:63', '1 Chronicles', 6, 63, '&nbsp;هم دغه شان، د روبين، جاد او زبولون په علاقو کښې دولس ښارونه د مرارى قبيلې ته خاندان په خاندان حواله شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9919, '1 Chronicles 6:64', '1 Chronicles', 6, 64, '&nbsp;نو داسې بنى اِسرائيلو ليويانو ته د اوسېدو دپاره ښارونه حواله کړل، سره د څرن د زمکې چې د دې ښارونو نه ګېرچاپېره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9920, '1 Chronicles 6:65', '1 Chronicles', 6, 65, '&nbsp;د يهوداه، شمعون او بنيامين په علاقه کښې هغه ښارونه هم د پچې په ذريعه حواله شوى وُو. د هغه ښارونو ذِکر وړاندې شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9921, '1 Chronicles 6:66', '1 Chronicles', 6, 66, '&nbsp;د قُهات قبيلې څۀ کورَنو ته د اِفرائيم په علاقه کښې ښارونه او د څرن زمکې حواله شوې وې:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9922, '1 Chronicles 6:67', '1 Chronicles', 6, 67, '&nbsp;شِکم چې د اِفرائيم په غرونو کښې د پناه ښار دے او ورسره جزر،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9923, '1 Chronicles 6:68', '1 Chronicles', 6, 68, '&nbsp;يُقمام، بيت‌حورون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9924, '1 Chronicles 6:69', '1 Chronicles', 6, 69, '&nbsp;ايالون او جات رِمون.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9925, '1 Chronicles 6:70', '1 Chronicles', 6, 70, '&nbsp;د قُهات پاتې اولاد ته د منسى د نيمې قبيلې د علاقې نه د عانير او بلعام ښارونه سره د ګېرچاپېره د څرن د زمکې حواله شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9926, '1 Chronicles 6:71', '1 Chronicles', 6, 71, '&nbsp;د جيرسون قبيلې کورَنو ته دا ښارونه، سره د ګېرچاپېره د څرن د زمکو حواله شوى وُو: د نمرخاتۀ منسى په علاقه کښې: په بسن کښې جولان، او عستارات.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9927, '1 Chronicles 6:72', '1 Chronicles', 6, 72, '&nbsp;د يساکار په علاقه کښې: قادِس، دبرت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9928, '1 Chronicles 6:73', '1 Chronicles', 6, 73, '&nbsp;رامات او عانيم چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9929, '1 Chronicles 6:74', '1 Chronicles', 6, 74, '&nbsp;د آشر په علاقه کښې: مسل، عبدون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9930, '1 Chronicles 6:75', '1 Chronicles', 6, 75, '&nbsp;حُقوق او رِحوب چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9931, '1 Chronicles 6:76', '1 Chronicles', 6, 76, '&nbsp;د نفتالى په علاقه کښې: په ګليل کښې قادِس، حمون او قِريَتائم چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9932, '1 Chronicles 6:77', '1 Chronicles', 6, 77, '&nbsp;د مرارى قبيلې باقى پاتې کورَنو ته دا ښارونه سره د دې نه ګېرچاپېره د څرن د زمکو حواله شوى وُو: د زبولون په علاقه کښې: رِمون او تبور.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9933, '1 Chronicles 6:78', '1 Chronicles', 6, 78, '&nbsp;د اُردن سيند نه پورې د يريحو نمرخاتۀ طرف ته، د روبين په علاقه کښې: په اوچته زمکه باندې بصر، يهض،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9934, '1 Chronicles 6:79', '1 Chronicles', 6, 79, '&nbsp;قديمات او مفعت چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9935, '1 Chronicles 6:80', '1 Chronicles', 6, 80, '&nbsp;د جاد په علاقه کښې: په جِلعاد کښې رامات، محنايم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9936, '1 Chronicles 6:81', '1 Chronicles', 6, 81, '&nbsp;حسبون او يعزير چې د څرن زمکې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9937, '1 Chronicles 7:1', '1 Chronicles', 7, 1, '&nbsp;د يساکار څلور زامن وُو: تولع، فُوه، يسوب او سِمرون.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9938, '1 Chronicles 7:2', '1 Chronicles', 7, 2, '&nbsp;د تولع شپږ زامن وُو: عُزى، رفاياه، يرى‌اېل، يحمى، ابسام او سموئيل. هغوئ د تولع د قبيلې اولنى مشران وُو. د داؤد بادشاه په زمانه کښې د دې ډلو د ټولو تکړه فوجيانو شمېر دوويشت زره او شپږ سوه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9939, '1 Chronicles 7:3', '1 Chronicles', 7, 3, '&nbsp;د عُزى يو زوئ اِزراخياه وو. اِزراخياه او د هغۀ څلور زامن، ميکائيل، عبدياه، يوايل او يسياه ټول د ډلو مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9940, '1 Chronicles 7:4', '1 Chronicles', 7, 4, '&nbsp;د هغوئ دومره ډېرې ښځې او بچى وُو چې د هغوئ اولاد د دې جوګه وو چې فوجى خِدمت له يې شپږ دېرش زره سړى ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9941, '1 Chronicles 7:5', '1 Chronicles', 7, 5, '&nbsp;د منلے شوى حِساب کِتاب په مطابق د يساکار قبيلې د ټولو کورَنو اووۀ اتيا زره داسې سړى شمېرلے شوى وُو چې کوم د فوجى خِدمت کولو قابل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9942, '1 Chronicles 7:6', '1 Chronicles', 7, 6, '&nbsp;د بنيامين درې زامن وُو: بالع، بکر او يديعيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9943, '1 Chronicles 7:7', '1 Chronicles', 7, 7, '&nbsp;د بالع پينځۀ زامن وُو: اصبان، عُزى، عُزى‌اېل، يريموت او عيرى. د هغوئ په ډله کښې د قبيلو مشران او تکړه فوجيان وُو. د هغوئ په اولاد کښې دوويشت زره او څلور دېرش سړى شامل وُو چې د فوجى کار کولو قابل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9944, '1 Chronicles 7:8', '1 Chronicles', 7, 8, '&nbsp;د بکر نهۀ زامن وُو: زميره، يوآس، اِلى‌عزر، اليوعينى، عُمرى، يريموت، ابياه، عنتوت او علمت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9945, '1 Chronicles 7:9', '1 Chronicles', 7, 9, '&nbsp;د هغوئ په نسب‌نامه کښې شل زره او دوه سوه د قبيلو مشرانو او تکړه فوجيانو نومونه ليکلى شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9946, '1 Chronicles 7:10', '1 Chronicles', 7, 10, '&nbsp;د يديعيل يو زوئ بِلهان وو او د بِلهان اووۀ زامن وُو: يعوس، بنيامين، اهُود، کنعانه، زيتان، ترسيس او اخى‌سحر.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9947, '1 Chronicles 7:11', '1 Chronicles', 7, 11, '&nbsp;هغوئ د قبيلې مشران او تکړه فوجيان وُو. د هغوئ په اولاد کښې اوولس زره او دوه سوه داسې سړى شامل وو چې کوم د فوجى کار کولو قابل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9948, '1 Chronicles 7:12', '1 Chronicles', 7, 12, '&nbsp;د سفيم او حُفيم تعلق هم د دې قبيلې سره وو. حشيم د احير زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9949, '1 Chronicles 7:13', '1 Chronicles', 7, 13, '&nbsp;د نفتالى څلور زامن وُو: يحزى‌ايل، جونى، يصر، سلوم. هغوئ د يعقوب د بلې ښځې بِلهاه اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9950, '1 Chronicles 7:14', '1 Chronicles', 7, 14, '&nbsp;د منسى د آرامى وينځې نه دوه زامن اسرى‌اېل او مکير وُو. مکير د جِلعاد پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9951, '1 Chronicles 7:15', '1 Chronicles', 7, 15, '&nbsp;مکير يوه ښځه د حُفيم او يوه ښځه د سفيم دپاره وکړه. د هغۀ د خور نوم معکه وو. د مکير دوېم زوئ صِلافحاد وو او د هغۀ صِرف لوڼه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9952, '1 Chronicles 7:16', '1 Chronicles', 7, 16, '&nbsp;د مکير د ښځې معکې دوه زامن پېدا شول، چې په هغوئ باندې يې فرس او شرس نومونه کېښودل. د فرس دوه زامن اولام او رِقم وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9953, '1 Chronicles 7:17', '1 Chronicles', 7, 17, '&nbsp;او د اولام يو زوئ وو چې نوم يې بدان وو. دا ټول د جِلعاد اولاد دے چې د مکير زوئ او د منسى نمسے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9954, '1 Chronicles 7:18', '1 Chronicles', 7, 18, '&nbsp;د هغۀ د خور همولکت درې زامن وُو: اِشهود، ابيعزر او محله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9955, '1 Chronicles 7:19', '1 Chronicles', 7, 19, '&nbsp;د سميدع څلور زامن وُو: اخيان، شِکم، لِقحى او انيعام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9956, '1 Chronicles 7:20', '1 Chronicles', 7, 20, '&nbsp;دا نسل په نسل د اِفرائيم اولاد دے: سوتلح، بيرِد، تحت، اِليعده، تحت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9957, '1 Chronicles 7:21', '1 Chronicles', 7, 21, '&nbsp;زاباد او سوتلح. د اِفرائيم دوه نور زامن ايصر او اِليعد څوک چې په هغه وخت کښې ووژلے شول چې کله هغوئ د جات د خلقو د څاروو پټولو کوشش کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9958, '1 Chronicles 7:22', '1 Chronicles', 7, 22, '&nbsp;د هغوئ پلار اِفرائيم تر ډېرو ورځو پورې په هغوئ پسې غمژن وو او د هغۀ خپلوان تسلۍ ورکولو له ورله راتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9959, '1 Chronicles 7:23', '1 Chronicles', 7, 23, '&nbsp;هغه د خپلې ښځې سره بيا څملاستو او هغه اُميدواره شوه او يو زوئ يې پېدا شو. هغۀ ورباندې بريعاه نوم کېښودو، دا د هغه مصيبت په وجه چې د هغوئ په خاندان باندې راغلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9960, '1 Chronicles 7:24', '1 Chronicles', 7, 24, '&nbsp;د اِفرائيم يوه لور وه چې نوم يې سيراه وو. هغې د بره او ښکته بيت‌حورون او عُزن سيراه ښارونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
